package in.recallradar;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.boot.context.properties.EnableConfigurationProperties; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.core.Authentication; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.web.cors.*; import org.springframework.stereotype.Component; import java.io.*; import java.util.*;
@Configuration @EnableWebSecurity @EnableConfigurationProperties(AppProperties.class) class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} @Bean AuthenticationManager authenticationManager(){return new ProviderManager(List.of(new JwtAuthenticationProvider()));}
 @Bean SecurityFilterChain security(HttpSecurity h,JwtFilter filter,AppProperties p)throws Exception{return h.csrf(c->c.disable()).cors(c->c.configurationSource(r->{var x=new CorsConfiguration();x.setAllowedOrigins(List.of(p.corsOrigin()));x.setAllowedMethods(List.of("GET","POST","PATCH","PUT","DELETE","OPTIONS"));x.setAllowedHeaders(List.of("Authorization","Content-Type","X-Organization-Id","Idempotency-Key"));return x;})).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/health","/swagger-ui/**","/v3/api-docs/**").permitAll().anyRequest().authenticated()).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();}
 static class JwtAuthenticationProvider implements AuthenticationProvider {public Authentication authenticate(Authentication a){return a;} public boolean supports(Class<?> c){return true;}}
}
@Component class JwtFilter extends OncePerRequestFilter { private final TokenService tokens; JwtFilter(TokenService t){tokens=t;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws IOException,ServletException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{var u=tokens.subject(h.substring(7));var a=new UsernamePasswordAuthenticationToken(u,null,List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_USER")));org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){}}c.doFilter(r,s);} }
